#include "construction/PrefabNetworkLifecycle.hpp"
#include <algorithm>
namespace elysium::construction {StableId PrefabNetworkLifecycle::endpointId(StableId o,std::uint32_t s,NetworkOwner n){std::uint64_t x=o^(std::uint64_t(s)<<32)^std::uint64_t(n)*0x9e3779b97f4a7c15ULL;x^=x>>30;x*=0xbf58476d1ce4e5b9ULL;x^=x>>27;x*=0x94d049bb133111ebULL;return x^(x>>31);}bool PrefabNetworkLifecycle::place(StableId id,const std::vector<EndpointDecl>&d,std::vector<RegistrationEvent>&e){if(!id||objects_.contains(id))return false;std::set<StableId>seen;std::vector<EndpointState>v;for(auto&x:d){if(x.decorative)continue;auto eid=endpointId(id,x.localSlot,x.owner);if(!eid||!seen.insert(eid).second)return false;v.push_back({eid,id,x,true});e.push_back({RegistrationEvent::Kind::Register,x.owner,eid,id});}objects_[id]=std::move(v);return true;}bool PrefabNetworkLifecycle::disable(StableId id,std::vector<RegistrationEvent>&e){auto i=objects_.find(id);if(i==objects_.end())return false;for(auto&x:i->second)if(x.enabled){x.enabled=false;e.push_back({RegistrationEvent::Kind::Unregister,x.decl.owner,x.endpointId,id});e.push_back({RegistrationEvent::Kind::WakeOwner,x.decl.owner,x.endpointId,id});}return true;}bool PrefabNetworkLifecycle::destroy(StableId id,std::vector<RegistrationEvent>&e){disable(id,e);return objects_.erase(id)>0;}std::vector<EndpointState>PrefabNetworkLifecycle::snapshot()const{std::vector<EndpointState>o;for(auto&[id,v]:objects_)o.insert(o.end(),v.begin(),v.end());std::sort(o.begin(),o.end(),[](auto&a,auto&b){return a.endpointId<b.endpointId;});return o;}std::vector<std::string>PrefabNetworkLifecycle::preview(const std::vector<EndpointDecl>&d)const{std::vector<std::string>o;for(auto&x:d){if(x.decorative)continue;if(!x.portType)o.push_back("missing_port_type");if(!x.input&&!x.output)o.push_back("endpoint_no_direction");}return o;}}
